static int Delivery(int total) => total >= 1000 ? 0 : 100;
int actual = Delivery(1000);
int expected = 0;
Console.WriteLine(actual == expected ? "Проверка пройдена" : "Ошибка");

static int Delivery(int total) => total >= 1000 ? 0 : 100;
(int total, int expected)[] cases = [(999, 100), (1000, 0), (1001, 0)];
foreach (var (total, expected) in cases)
{
    Console.WriteLine($"{total} — {Delivery(total) == expected}");
}

